function uid(prefix='id'){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`}
function toLocalDate(date){const d=new Date(date.getTime()-date.getTimezoneOffset()*60000);return d.toISOString().slice(0,10)}
function postFromDb(row){return{id:row.id,caption:row.caption||'',link:DEFAULT_POST_URL,hashtags:row.hashtags||'',notes:row.notes||'',platforms:row.platforms||[],scheduledAt:row.scheduled_at,status:row.status,campaignId:row.campaign_id||'',mediaId:row.media_id||'',mediaName:row.media_name||'',createdAt:row.created_at,updatedAt:row.updated_at}}
function postToDb(post){return{id:post.id,caption:post.caption,link:DEFAULT_POST_URL,hashtags:post.hashtags||'',notes:post.notes||'',platforms:post.platforms||[],scheduled_at:post.scheduledAt,status:post.status,campaign_id:post.campaignId||null,media_id:post.mediaId||null,media_name:post.mediaName||'',created_at:post.createdAt,updated_at:post.updatedAt,updated_by:currentUser?.id||null}}
