function requestFromDb(row){return{id:row.id,type:row.request_type,title:row.title,details:row.details||'',priority:row.priority,status:row.status,requestedBy:row.requested_by,requestedByEmail:row.requested_by_email,requestedByName:row.requested_by_name,assignedTo:row.assigned_to_email||'',relatedPostId:row.related_post_id||'',relatedCampaignId:row.related_campaign_id||'',createdAt:row.created_at,updatedAt:row.updated_at}}
function threadFromDb(row){return{id:row.id,platform:row.platform,contactName:row.contact_name,contactHandle:row.contact_handle||'',subject:row.subject||'',status:row.status,createdBy:row.created_by,createdAt:row.created_at,updatedAt:row.updated_at,lastMessageAt:row.last_message_at}}
