function setAuthMessage(message='',success=false){el.authMessage.textContent=message;el.authMessage.classList.toggle('success',success)}
function setAuthMode(mode){authMode=mode;$$('[data-auth-mode]').forEach(b=>b.classList.toggle('active',b.dataset.authMode===mode));const signup=mode==='signup',recovery=mode==='recovery';el.authTitle.textContent=recovery?'Choose a new password':signup?'Create your account':'Welcome back';el.authSubtitle.textContent=recovery?'Enter a new password with at least eight characters.':signup?'Use an email already approved by your administrator.':'Sign in with your approved team email.';el.authSubmitButton.textContent=recovery?'Save new password':signup?'Create secure account':'Sign in securely';el.forgotPasswordButton.hidden=signup||recovery;el.authTabs.hidden=recovery;el.authEmail.closest('label').hidden=recovery;el.authPassword.autocomplete=signup||recovery?'new-password':'current-password';setAuthMessage()}
async function loadCloudData(){
  const [postsResult,campaignsResult,accountsResult,mediaResult,requestsResult,threadsResult,messagesResult]=await Promise.all([db.from('posts').select('*').order('scheduled_at'),db.from('campaigns').select('*').order('created_at'),db.from('social_accounts').select('*'),db.from('media_assets').select('*').order('created_at'),db.from('team_requests').select('*').order('updated_at',{ascending:false}),db.from('social_threads').select('*').order('last_message_at',{ascending:false}),db.from('social_messages').select('*').order('created_at')]);
  const coreError=postsResult.error||campaignsResult.error||accountsResult.error;if(coreError)throw coreError;schemaWarnings=[];if(mediaResult.error)schemaWarnings.push('media library');if(requestsResult.error)schemaWarnings.push('team requests');if(threadsResult.error||messagesResult.error)schemaWarnings.push('social inbox');
  state.posts=(postsResult.data||[]).map(postFromDb);state.campaigns=(campaignsResult.data||[]).map(campaignFromDb);state.media=mediaResult.error?[]:(mediaResult.data||[]).map(mediaFromDb);state.requests=requestsResult.error?[]:(requestsResult.data||[]).map(requestFromDb);state.threads=threadsResult.error?[]:(threadsResult.data||[]).map(threadFromDb);state.messages=messagesResult.error?[]:(messagesResult.data||[]).map(messageFromDb);state.accounts=Object.fromEntries(PLATFORMS.map(p=>[p.id,false]));(accountsResult.data||[]).forEach(row=>state.accounts[row.platform]=Boolean(row.ready));
}
async function verifyAndOpenWorkspace(user){
  if(!user||(currentUser?.id===user.id&&el.authGate.hidden))return;
  el.cloudLoading.hidden=false;el.authGate.hidden=true;
  try{
    const{data:allowed,error}=await db.rpc('is_allowed_user');if(error)throw error;
    if(!allowed){await db.auth.signOut();throw new Error('This email is not on the approved Tech Social team list. Ask the administrator to add it in Supabase.')}
    currentUser=user;const profileResult=await db.from('allowed_users').select('display_name');await loadCloudData();
    const email=user.email||'Team member',profileName=profileResult.data?.[0]?.display_name?.trim(),name=profileName||user.user_metadata?.display_name||email.split('@')[0].replace(/[._-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase()),initials=name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();currentDisplayName=name;el.userDisplayName.textContent=name;el.userEmailLabel.textContent=email;el.dropdownEmail.textContent=email;el.userInitials.textContent=initials||'TL';el.profileDisplayName.value=name;el.profileEmail.value=email;el.profileAvatar.textContent=initials||'TL';
    if(!appInitialized){renderPlatformPicker();renderColourPicker();bindEvents();el.postDate.min=toLocalDate(new Date());appInitialized=true;if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{})}
    setDateGreeting();renderAll();showView('dashboard',false);subscribeRealtime();el.cloudLoading.hidden=true;el.authGate.hidden=true;if(schemaWarnings.length)setTimeout(()=>toast(`Database migration required for: ${schemaWarnings.join(', ')}. Core CRM access is still available.`,true),300);
  }catch(error){currentUser=null;el.cloudLoading.hidden=true;el.authGate.hidden=false;el.setupPanel.hidden=true;el.loginPanel.hidden=false;setAuthMode('signin');setAuthMessage(error.message||'Could not open the shared workspace.')}
}
function subscribeRealtime(){if(realtimeChannel)db.removeChannel(realtimeChannel);realtimeChannel=db.channel('tech-social-team').on('postgres_changes',{event:'*',schema:'public',table:'posts'},scheduleCloudRefresh).on('postgres_changes',{event:'*',schema:'public',table:'campaigns'},scheduleCloudRefresh).on('postgres_changes',{event:'*',schema:'public',table:'social_accounts'},scheduleCloudRefresh).on('postgres_changes',{event:'*',schema:'public',table:'media_assets'},scheduleCloudRefresh).on('postgres_changes',{event:'*',schema:'public',table:'team_requests'},scheduleCloudRefresh).on('postgres_changes',{event:'*',schema:'public',table:'social_threads'},scheduleCloudRefresh).on('postgres_changes',{event:'*',schema:'public',table:'social_messages'},scheduleCloudRefresh).subscribe()}
function scheduleCloudRefresh(){clearTimeout(realtimeTimer);realtimeTimer=setTimeout(async()=>{if(!currentUser)return;try{await loadCloudData();renderAll()}catch{}},250)}
async function initializeAuth(){
  bindAuthEvents();
  if(!configReady()){el.loginPanel.hidden=true;el.setupPanel.hidden=false;el.authGate.hidden=false;return}
  try{
    db=window.supabase.createClient(window.TECH_SOCIAL_CONFIG.supabaseUrl,window.TECH_SOCIAL_CONFIG.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
    db.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){setAuthMode('recovery');el.authGate.hidden=false;el.loginPanel.hidden=false;el.setupPanel.hidden=true;el.cloudLoading.hidden=true}else if(event==='SIGNED_OUT'){currentUser=null;currentDisplayName='';el.authGate.hidden=false;el.loginPanel.hidden=false;el.setupPanel.hidden=true;el.userDropdown.hidden=true}else if(event==='SIGNED_IN'&&session?.user){setTimeout(()=>verifyAndOpenWorkspace(session.user),0)}});
    const{data:{session}}=await db.auth.getSession();if(session?.user)await verifyAndOpenWorkspace(session.user);else{el.authGate.hidden=false;el.loginPanel.hidden=false;el.setupPanel.hidden=true}
  }catch(error){el.loginPanel.hidden=false;el.setupPanel.hidden=true;setAuthMessage(`Supabase connection failed: ${error.message}`)}
}
function bindAuthEvents(){
  $$('[data-auth-mode]').forEach(button=>button.addEventListener('click',()=>setAuthMode(button.dataset.authMode)));
  el.authForm.addEventListener('submit',handleAuthSubmit);el.forgotPasswordButton.addEventListener('click',handleForgotPassword);el.recheckConfigButton.addEventListener('click',()=>location.reload());
  el.userMenuButton.addEventListener('click',event=>{event.stopPropagation();el.userDropdown.hidden=!el.userDropdown.hidden});el.logoutButton.addEventListener('click',async()=>{el.userDropdown.hidden=true;await db.auth.signOut();state={posts:[],campaigns:[],media:[],requests:[],threads:[],messages:[],accounts:{}}});document.addEventListener('click',event=>{if(!event.target.closest('.user-menu-wrap'))el.userDropdown.hidden=true});
}
async function handleAuthSubmit(event){event.preventDefault();if(!db)return;const email=el.authEmail.value.trim().toLowerCase(),password=el.authPassword.value;setAuthMessage();el.authSubmitButton.disabled=true;el.authSubmitButton.textContent='Please wait…';try{
  if(authMode==='recovery'){const{error}=await db.auth.updateUser({password});if(error)throw error;setAuthMessage('Password updated. Opening your workspace…',true);const{data:{user}}=await db.auth.getUser();await verifyAndOpenWorkspace(user);return}
  if(authMode==='signup'){const{data,error}=await db.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;if(data.session)await verifyAndOpenWorkspace(data.user);else setAuthMessage('Check your email and confirm the account, then return here to sign in.',true)}
  else{const{data,error}=await db.auth.signInWithPassword({email,password});if(error)throw error;await verifyAndOpenWorkspace(data.user)}
 }catch(error){setAuthMessage(error.message||'Authentication failed.')}finally{el.authSubmitButton.disabled=false;el.authSubmitButton.textContent=authMode==='recovery'?'Save new password':authMode==='signup'?'Create secure account':'Sign in securely'}
}
async function handleForgotPassword(){if(!db)return;const email=el.authEmail.value.trim().toLowerCase();if(!email){setAuthMessage('Enter your approved email address first.');return}const{error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});setAuthMessage(error?error.message:'Password reset email sent. Check your inbox.',!error)}
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function normaliseHashtags(value=''){return value.split(/[\s,]+/).map(t=>t.replace(/^#+/,'').replace(/[^\p{L}\p{N}_]/gu,'')).filter(Boolean).map(t=>`#${t}`).join(' ')}
function buildCaption(post){return[post.caption?.trim(),normaliseHashtags(post.hashtags)].filter(Boolean).join('\n\n')}
function formatDateTime(value,short=false){if(!value)return'Unscheduled';const d=new Date(value);return new Intl.DateTimeFormat('en-GB',short?{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}:{weekday:'short',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)}
function formatDayMonth(value){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short'}).format(new Date(value))}
function platform(id){return PLATFORMS.find(p=>p.id===id)}
function campaign(id){return state.campaigns.find(c=>c.id===id)}
function postTitle(post){const text=post.caption?.trim()||'Untitled post';return text.length>72?`${text.slice(0,72)}…`:text}
function statusPill(status){return `<span class="status-pill ${status}">${escapeHtml(STATUSES[status]||status)}</span>`}
function platformBadges(ids=[]){return `<div class="platform-stack">${ids.slice(0,4).map(id=>{const p=platform(id);return p?`<span class="network-badge" title="${p.name}" style="background:${p.color}">${p.badge}</span>`:''}).join('')}${ids.length>4?`<span class="network-badge" style="background:#777">+${ids.length-4}</span>`:''}</div>`}
function campaignTag(id){const c=campaign(id);return c?`<span class="campaign-tag"><i style="background:${c.colour}"></i>${escapeHtml(c.name)}</span>`:'<span class="campaign-tag">No campaign</span>'}
function sortedPosts(){return[...state.posts].sort((a,b)=>new Date(a.scheduledAt)-new Date(b.scheduledAt))}
function queuePosts(){return sortedPosts().filter(p=>p.status!=='published'&&p.scheduledAt)}
function isDue(post){return post.scheduledAt&&new Date(post.scheduledAt)<=new Date()&&post.status!=='published'}

