function renderSettings(){el.profileDisplayName.value=currentDisplayName;el.profileEmail.value=currentUser?.email||'';el.profileAvatar.textContent=(currentDisplayName||'TL').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();el.versionHistory.innerHTML=VERSION_HISTORY.map((release,index)=>`<article class="version-card ${index===0?'current':''}"><header><h4>Version ${release.version}${index===0?' · Current':''}</h4><time>${release.date}</time></header><p>${release.summary}</p><ul>${release.changes.map(change=>`<li>${escapeHtml(change)}</li>`).join('')}</ul></article>`).join('')}
