function compareVersions(a,b){const pa=String(a).split('.').map(Number),pb=String(b).split('.').map(Number);for(let i=0;i<Math.max(pa.length,pb.length);i++){if((pa[i]||0)!==(pb[i]||0))return(pa[i]||0)-(pb[i]||0)}return 0}
async function checkForUpdates(){el.checkVersionButton.disabled=true;el.versionStatus.textContent='Checking for updates…';try{const response=await fetch(`version.json?time=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error('Version information unavailable.');const info=await response.json();el.versionStatus.textContent=compareVersions(info.version,APP_VERSION)>0?`Version ${info.version} is available. Refresh after the repository update is deployed.`:`You are up to date on version ${APP_VERSION}.`}catch(error){el.versionStatus.textContent=error.message}finally{el.checkVersionButton.disabled=false}}

function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`tech-social-crm-backup-${toLocalDate(new Date())}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);toast('CRM backup downloaded.')}
function importData(){const file=el.importInput.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=async()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data.posts)||!Array.isArray(data.campaigns))throw new Error('Invalid backup format.');if(!confirm('Replace the shared CRM data with this backup for every team member?'))return;const campaigns=data.campaigns.map(c=>({...c,updatedAt:c.updatedAt||new Date().toISOString()})),posts=data.posts.map(p=>({...p,createdAt:p.createdAt||new Date().toISOString(),updatedAt:p.updatedAt||new Date().toISOString()})),accounts={...Object.fromEntries(PLATFORMS.map(p=>[p.id,false])),...(data.accounts||{})};let result=await db.from('posts').delete().not('id','is',null);if(result.error)throw result.error;result=await db.from('campaigns').delete().not('id','is',null);if(result.error)throw result.error;if(campaigns.length){result=await db.from('campaigns').upsert(campaigns.map(campaignToDb));if(result.error)throw result.error}if(posts.length){result=await db.from('posts').upsert(posts.map(postToDb));if(result.error)throw result.error}result=await db.from('social_accounts').upsert(PLATFORMS.map(p=>({platform:p.id,ready:Boolean(accounts[p.id]),updated_at:new Date().toISOString(),updated_by:currentUser.id})));if(result.error)throw result.error;state={posts,campaigns,media:state.media,requests:state.requests,threads:state.threads,messages:state.messages,accounts};renderAll();toast('Shared CRM backup imported. Media files already in the library were preserved.')}catch(error){toast(error.message||'That file is not a valid Tech Social CRM backup.',true)}finally{el.importInput.value=''}};reader.readAsText(file)}
